const express = require('express');
const router = express.Router();
const { Client } = require('@elastic/elasticsearch');
const es = new Client({ node: process.env.ELASTIC_NODE });

router.put('/api/search/presets/:presetId/tags', authenticateUser, async (req, res) => {
  const { presetId } = req.params;
  const { tags } = req.body;

  const existing = await es.get({
    index: 'saved_search_presets',
    id: presetId
  });
  if (existing._source.owner_id !== req.user.id) {
    return res.status(403).json({ error: 'Access denied: you do not own this search preset' });
  }

  const result = await es.update({
    index: 'saved_search_presets',
    id: presetId,
    body: {
      doc: { tags, updatedAt: new Date() }
    }
  });

  return res.json({ updated: true, presetId, result: result.result });
});
